input.command:
sed -n '1042,4506p' all.md | grep -vE '^!\[|^$|^Elapsed|^Remaining|^0\.25' | awk '
/^(January|February|March|April|May|June|July|August|September|October|November|December) [0-9]+, 20/ {print "=== " $0; next}
/^\[\*\*/ {print "## " substr($0,1,120); next}
/^(API|MCP server|MCP|Webhooks|OAuth)( \([0-9]+\))?$/ {p=1; print "-- " $0; n=0; next}
/^(Improvements|Fixes|Fixed|Changelog)/ {p=0}
p && n<14 {print substr($0,1,330); n++}
/^- (API|MCP|Webhooks|OAuth|OAuth apps|API Keys)/ {print "** " $0}
' > api.txt; wc -l api.txt

