input.command:
sed -n '1042,4506p' all.md | iconv -c -f utf-8 -t utf-8 | grep -vE '^!\[|^$' | awk '
/^(January|February|March|April|May|June|July|August|September|October|November|December) [0-9]+, 20/ {print "=== " $0; next}
/^- (API|MCP|Webhooks|OAuth|OAuth apps|OAuth Apps|API Keys|OAuth applications|Authentication)$/ {print "-- " $0; getline; print "   " substr($0,1,300); next}
/^(API|MCP server|MCP)( \([0-9]+\))?$/ {print "## SECTION " $0}
' | awk '/^===/{d=$0; next} {if(d){print d; d=""} print}' > hits.txt; wc -l hits.txt; cat hits.txt

